def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    desperate_count = 0
    rich_aggressive_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            if opp.get('budget', 0) >= 700:
                rich_aggressive_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(float(prev.get('bid', 0.0)))

    if not alive_opps:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    moderate_prev = 0.0
    for b in prev_bids:
        if b <= 85 and b > moderate_prev:
            moderate_prev = b

    scarcity = (float(supply) <= 18.0)
    severe_scarcity = (float(supply) <= 16.0)

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water >= 2:
        urgency += 3
    elif no_water >= 1:
        urgency += 2

    if scarcity:
        urgency += 1
    if severe_scarcity:
        urgency += 1
    if day >= 8:
        urgency += 1

    if urgency <= 1:
        base = 12.0 if not scarcity else 16.0
    elif urgency == 2:
        base = 24.0 if not scarcity else 31.0
    elif urgency == 3:
        base = 42.0 if not scarcity else 52.0
    elif urgency == 4:
        base = 58.0 if not scarcity else 68.0
    else:
        base = 78.0 if not scarcity else 90.0

    if moderate_prev > 0:
        target = moderate_prev + 2.0
        if urgency >= 3:
            base = max(base, target)
        else:
            base = min(base, target)

    if highest_prev >= 100.0 and urgency <= 3:
        base = min(base, 26.0 if not scarcity else 34.0)
    elif highest_prev >= 85.0 and urgency <= 2:
        base = min(base, 32.0 if not scarcity else 40.0)

    if desperate_count >= 2 and urgency <= 2:
        base *= 0.85
    if rich_aggressive_count >= 2 and urgency <= 3:
        base *= 0.9

    if hp <= 2 or no_water >= 2:
        base = max(base, 88.0 if scarcity else 76.0)

    if day >= 9 and hp <= 4:
        base = max(base, 82.0)

    affordable_cap = budget
    if day <= 3:
        affordable_cap = min(affordable_cap, 95.0)
    elif day <= 6:
        affordable_cap = min(affordable_cap, 110.0)
    else:
        affordable_cap = min(affordable_cap, 130.0)

    bid = min(affordable_cap, base)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

