def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context.get('supply', 0.0)
    day = day_context.get('day', 0)

    my_hp = my_status.get('hp', 0)
    my_budget = my_status.get('budget', 0)
    my_no_water_days = my_status.get('no_water_days', 0)

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append(opp)

    if not alive_opponents:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.35))

    # Yesterday trace reaction (only immediate)
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                yesterday_bids.append(float(bid))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Estimate how many water units are likely available; use conservative discretization.
    # supply is float; indices must be int if used.
    # We'll map supply to a rough unit count.
    approx_units = int(max(1.0, supply / float(WATER_REQ)))
    # Competition factor: more alive opponents => bid more.
    n_alive = len(alive_opponents)

    # Baseline: aim for a competitive fraction of salary.
    # If yesterday pressure was high, raise bid.
    pressure = 0.0
    if highest_prev_bid > 0:
        pressure = min(1.0, highest_prev_bid / float(DAILY_SALARY))

    # HP urgency: if low HP or many no-water days, increase.
    hp_urgency = 0.0
    if my_hp <= 2:
        hp_urgency = 1.0
    elif my_hp <= 4:
        hp_urgency = 0.7
    elif my_hp <= 6:
        hp_urgency = 0.4
    else:
        hp_urgency = 0.2

    # No-water-days urgency
    nw_urgency = 0.0
    if my_no_water_days >= 3:
        nw_urgency = 1.0
    elif my_no_water_days == 2:
        nw_urgency = 0.7
    elif my_no_water_days == 1:
        nw_urgency = 0.4
    else:
        nw_urgency = 0.2

    # Unit scarcity factor: fewer units => higher bid.
    scarcity = 0.0
    if approx_units <= 1:
        scarcity = 1.0
    elif approx_units == 2:
        scarcity = 0.7
    else:
        scarcity = 0.4

    # Combine into target spend.
    # Also incorporate opponent count: more opponents => raise.
    opponent_factor = 0.45 + 0.15 * min(4, n_alive)

    target_fraction = 0.25 + 0.45 * pressure + 0.25 * hp_urgency + 0.2 * nw_urgency + 0.2 * scarcity
    target_fraction *= opponent_factor

    # Cap target fraction to avoid bankruptcy; still aggressive enough to compete.
    target_fraction = min(0.95, max(0.15, target_fraction))

    # Convert to bid. Keep it within budget.
    bid = DAILY_SALARY * target_fraction

    # If we are extremely low budget, bid a minimal survival amount.
    if my_budget <= DAILY_SALARY * 0.15:
        bid = min(my_budget, DAILY_SALARY * 0.2)
    else:
        bid = min(my_budget, bid)

    # If yesterday max bid was very high, slightly overbid relative to baseline.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        bid = min(my_budget, max(bid, DAILY_SALARY * 0.35 + 0.05 * (highest_prev_bid - DAILY_SALARY * 0.85)))

    # Final clamp
    if bid < 0:
        bid = 0.0
    return float(bid)
